plicacao":"Líder da Inconfidência Mineira."},{"id":6997,"materia":"his","nivel":0,"enunciado":"O feriado de 15 de novembro lembra:","opcoes":["A Proclamação da República","A Independência","A abolição da escravatura","O Descobrimento"],"explicacao":"Em 1889."},{"id":6998,"materia":"his","nivel":2,"enunciado":"A política romana do \"pão e circo\" servia para:","opcoes":["Distrair a população e evitar revoltas","Ensinar o povo romano a ler e escrever","Treinar soldados para as guerras","Exportar trigo"],"explicacao":"Distribuía alimento e oferecia espetáculos."},{"id":6999,"materia":"his","nivel":2,"enunciado":"As Grandes Navegações dos séculos XV e XVI foram motivadas, entre outros fatores, pela busca de:","opcoes":["Especiarias e novas rotas para as Índias","Petróleo para as indústrias europeias","Ouro na Antártida","Refugiados"],"explicacao":"O comércio pelo Mediterrâneo estava dominado por outros povos."},{"id":7000,"materia":"his","nivel":1,"enunciado":"Os quilombos, no Brasil colonial, representavam:","opcoes":["Resistência à escravidão","Centros de comércio de escravizados","Aldeias de missionários","Fortes portugueses"],"explicacao":"Palmares foi o mais famoso."},{"id":7001,"materia":"his","nivel":1,"enunciado":"O movimento sufragista lutava pelo:","opcoes":["Direito das mulheres ao voto","Fim da monarquia na Inglaterra","Direito à greve dos operários","Fim das guerras"],"explicacao":"Ganhou força no início do século XX."},{"id":7002,"materia":"his","nivel":2,"enunciado":"No Brasil, as mulheres conquistaram o direito de votar em:","opcoes":["1932","1889","1988","1822"],"explicacao":"Pelo Código Eleitoral do governo Vargas."},{"id":7003,"materia":"his","nivel":3,"enunciado":"A Revolução de 1930 pôs fim:","opcoes":["À República Velha e ao café com leite","Ao Império de Dom Pedro II","Ao Estado Novo de Vargas","À ditadura militar"],"explicacao":"Levou Getúlio Vargas ao poder."},{"id":7004,"materia":"his","nivel":4,"enunciado":"A Lei da Anistia de 1979:","opcoes":["Perdoou crimes políticos, inclusive de agentes do Estado","Puniu os torturadores da ditadura militar","Aboliu a censura e convocou eleições diretas","Criou o voto feminino"],"explicacao":"Permitiu a volta de exilados, mas segue polêmica."},{"id":7005,"materia":"his","nivel":4,"enunciado":"A maior parte dos países africanos conquistou a independência:","opcoes":["Entre as décadas de 1950 e 1970","No século XVI, com as navegações","Antes da Primeira Guerra Mundial","Depois de 2000"],"explicacao":"Processo de descolonização após a Segunda Guerra."},{"id":7006,"materia":"his","nivel":4,"enunciado":"A Revolução Haitiana (1791-1804) foi marcante porque:","opcoes":["Criou a primeira república de ex-escravizados","Fez do Haiti uma colônia inglesa","Restaurou a monarquia francesa na ilha","Ocorreu sem participação popular"],"explicacao":"Também aboliu a escravidão na ilha."},{"id":7007,"materia":"geo","nivel":0,"enunciado":"O Sol nasce, aproximadamente, no:","opcoes":["Leste","Oeste","Norte","Sul"],"explicacao":"E se põe no oeste."},{"id":7008,"materia":"geo","nivel":0,"enunciado":"O GPS do celular localiza o aparelho com a ajuda de:","opcoes":["Satélites","Bússolas de papel","Rádios AM","Mapas impressos"],"explicacao":"Calcula a posição por sinais de vários satélites."},{"id":7009,"materia":"geo","nivel":1,"enunciado":"Na coleta seletiva, a lixeira azul é para:","opcoes":["Papel","Vidro","Metal","Plástico"],"explicacao":"Vermelho é plástico; verde, vidro; amarelo, metal."},{"id":7010,"materia":"geo","nivel":2,"enunciado":"A diferença entre lixão e aterro sanitário é que o aterro:","opcoes":["Impermeabiliza o solo e trata o chorume","Queima o lixo a céu aberto todo dia","Joga o lixo tratado nos rios","Não precisa de licença"],"explicacao":"O lixão contamina solo e água."},{"id":7011,"materia":"geo","nivel":2,"enunciado":"No Pantanal e na Amazônia, as queimadas aumentam principalmente na estação:","opcoes":["Seca","Chuvosa","Do inverno com neve","De cheia dos rios"],"explicacao":"A vegetação seca pega fogo mais fácil."},{"id":7012,"materia":"geo","nivel":2,"enunciado":"O bioma que só existe no Brasil é a:","opcoes":["Caatinga","Amazônia","Mata Atlântica","Pampa"],"explicacao":"Os outros se estendem a países vizinhos."},{"id":7013,"materia":"geo","nivel":3,"enunciado":"Quem mora numa cidade e trabalha em outra, indo e voltando todo dia, faz migração:","opcoes":["Pendular","Sazonal","Internacional","Transumante"],"explicacao":"Comum nas regiões metropolitanas."},{"id":7014,"materia":"geo","nivel":4,"enunciado":"Nos últimos anos, a maior parte dos migrantes venezuelanos entrou no Brasil por:","opcoes":["Roraima","Rio Grande do Sul","Acre","Amapá"],"explicacao":"Pela fronteira em Pacaraima."},{"id":7015,"materia":"geo","nivel":3,"enunciado":"No Brasil, as áreas mais afetadas pela desertificação ficam:","opcoes":["No semiárido nordestino","Na Amazônia central","No litoral do Sul","Na Serra do Mar"],"explicacao":"Clima seco e uso inadequado do solo."},{"id":7016,"materia":"geo","nivel":4,"enunciado":"No sudoeste do Rio Grande do Sul, o processo de formação de areais em solos frágeis do Pampa é chamado de:","opcoes":["Arenização","Desertificação climática","Laterização","Salinização"],"explicacao":"Não é deserto: a região tem chuvas regulares."},{"id":7017,"materia":"fil","nivel":0,"enunciado":"A ética é a área da filosofia que reflete sobre:","opcoes":["O certo e o errado no agir humano","O movimento dos astros","Os números e as formas","As rochas"],"explicacao":"Pergunta como devemos viver."},{"id":7018,"materia":"fil","nivel":0,"enunciado":"Julgar alguém sem conhecê-lo, a partir de ideias prontas, é:","opcoes":["Preconceito","Empatia","Pesquisa","Argumentação"],"explicacao":"Pré-conceito: um juízo antecipado."},{"id":7019,"materia":"fil","nivel":2,"enunciado":"Considerar estranha ou inferior a cultura de outro povo, tomando a própria como padrão, é:","opcoes":["Etnocentrismo","Relativismo cultural","Aculturação","Multiculturalismo"],"explicacao":"O relativismo busca entender cada cultura em seus termos."},{"id":7020,"materia":"fil","nivel":3,"enunciado":"Entender os costumes de outro povo a partir dos valores dele, e não dos nossos, é:","opcoes":["Relativismo cultural","Etnocentrismo","Xenofobia","Assimilação cultural"],"explicacao":"Base do trabalho antropológico."},{"id":7021,"materia":"fil","nivel":4,"enunciado":"Num debate, alguém responde: \"Você não pode falar de economia porque nunca teve empresa\". Isso é a falácia:","opcoes":["Ad hominem (ataque à pessoa)","Apelo à autoridade","Falsa causa (post hoc)","Generalização apressada"],"explicacao":"Ataca-se quem fala, não o argumento."},{"id":7022,"materia":"fil","nivel":3,"enunciado":"Nas redes sociais, os algoritmos tendem a mostrar conteúdos que:","opcoes":["Reforçam o que o usuário já pensa (bolhas)","Contrariam sempre a opinião do usuário","São escolhidos totalmente ao acaso","Vêm só de jornais oficiais"],"explicacao":"Isso favorece a polarização."},{"id":7023,"materia":"fil","nivel":4,"enunciado":"Recusar-se publicamente e sem violência a cumprir uma lei considerada injusta, como propôs Thoreau, é:","opcoes":["Desobediência civil","Golpe de Estado","Anarquia armada","Crime de guerra"],"explicacao":"Inspirou Gandhi e Martin Luther King."},{"id":7024,"materia":"fil","nivel":3,"enunciado":"Quando Aristóteles diz que \"o homem é um animal político\", quer dizer que o ser humano:","opcoes":["Se realiza vivendo em comunidade (a pólis)","Deve ser político de profissão","Vive melhor isolado na natureza","É igual aos outros animais"],"explicacao":"Fora da cidade, seria \"um deus ou uma besta\"."},{"id":7025,"materia":"fil","nivel":4,"enunciado":"Para Marx, a ideologia é:","opcoes":["Ideias da classe dominante que ocultam a exploração","Uma ciência neutra e objetiva","A religião oficial do Estado","O estudo das ideias de Platão"],"explicacao":"Faz a desigualdade parecer natural."},{"id":7026,"materia":"bio","nivel":1,"enunciado":"Uma pessoa toma antibiótico por 3 dias, melhora e para por conta própria. O risco dessa atitude é:","opcoes":["A infecção voltar com bactérias mais resistentes","Ficar imune àquela bactéria para sempre","Pegar uma gripe por causa do remédio","Nenhum, se melhorou"],"explicacao":"O tratamento deve ir até o fim."},{"id":7027,"materia":"bio","nivel":2,"enunciado":"Na geladeira, os alimentos demoram mais a estragar porque o frio:","opcoes":["Desacelera o crescimento de microrganismos","Mata todos os microrganismos presentes","Retira as vitaminas dos alimentos","Adiciona conservantes"],"explicacao":"Ao sair da geladeira, eles voltam a se multiplicar."},{"id":7028,"materia":"bio","nivel":4,"enunciado":"Um agricultor percebe que, após anos usando o mesmo inseticida, a praga voltou mais forte. A explicação biológica é:","opcoes":["O veneno selecionou os insetos resistentes","Os insetos aprenderam a evitar o veneno","O inseticida virou alimento para a praga","A praga mudou de espécie em um ano"],"explicacao":"É seleção natural em ação."},{"id":7029,"materia":"geo","nivel":1,"enunciado":"Um aplicativo mostra que a temperatura em Porto Alegre está muito mais baixa que em Fortaleza no mesmo dia de julho. Um fator que explica isso é a:","opcoes":["Latitude","Longitude","Língua falada","Altitude do mar"],"explicacao":"Quanto mais longe do Equador, menor a insolação no inverno."},{"id":7030,"materia":"geo","nivel":2,"enunciado":"Muitas pessoas trocam o carro pelo metrô nas grandes cidades. Isso ajuda a:","opcoes":["Reduzir congestionamentos e poluição","Aumentar o consumo de combustível","Aumentar as ilhas de calor","Desmatar as periferias"],"explicacao":"O transporte coletivo leva mais gente com menos emissão."},{"id":7031,"materia":"geo","nivel":3,"enunciado":"Num mapa, uma área de reserva aparece com 4 cm² na escala 1:100.000. Sua área real é de:","opcoes":["4 km²","40 km²","0,4 km²","400 km²"],"explicacao":"1 cm = 1 km, então 1 cm² = 1 km²."},{"id":7032,"materia":"his","nivel":2,"enunciado":"Um museu exibe uma carta de alforria do século XIX. Esse documento:","opcoes":["Concedia a liberdade a uma pessoa escravizada","Registrava a venda de terras devolutas","Era um título de nobreza do Império","Autorizava o voto"],"explicacao":"Podia ser comprada ou concedida pelo senhor."},{"id":7033,"materia":"his","nivel":3,"enunciado":"Numa aula sobre a ditadura militar, a professora mostra uma música com letra ambígua que escapou da censura. Esse recurso era usado para:","opcoes":["Criticar o regime de forma disfarçada","Elogiar os militares no poder","Vender mais discos no exterior","Ensinar inglês"],"explicacao":"Chico Buarque foi um dos artistas que usaram duplos sentidos."},{"id":7034,"materia":"fil","nivel":1,"enunciado":"Um grupo decide, por votação, que a maioria escolhe o passeio da turma, mas respeitando quem não pode pagar. Isso combina com a ideia de democracia com:","opcoes":["Respeito às minorias","Poder de um só","Exclusão dos que discordam","Sorteio sem regras"],"explicacao":"Democracia não é só vontade da maioria."},{"id":7035,"materia":"fil","nivel":4,"enunciado":"Um filme mostra pessoas que trabalham muitas horas e ainda assim não reconhecem o produto do próprio trabalho como seu. Marx chamaria isso de:","opcoes":["Alienação","Mais-valia absoluta, apenas","Ideologia religiosa","Socialização"],"explicacao":"O trabalhador se torna estranho ao que produz."},{"id":7036,"materia":"qui","nivel":3,"enunciado":"Ao abrir uma garrafa de refrigerante quente, sai mais gás do que se estivesse gelada porque:","opcoes":["A solubilidade dos gases cai quando a temperatura sobe","O gás dissolvido aumenta quando o líquido esfria","O açúcar se transforma em gás no calor","A garrafa fica mais pesada"],"explicacao":"Líquidos frios retêm mais gás dissolvido."},{"id":7037,"materia":"fis","nivel":3,"enunciado":"Num dia quente, os fios dos postes ficam mais \"barrigudos\" do que no frio porque:","opcoes":["Dilatam com o calor","Encolhem com o calor","Ficam mais pesados","Perdem eletricidade"],"explicacao":"Por isso são instalados com folga."},{"id":7038,"materia":"mat","nivel":2,"enunciado":"Uma pesquisa mostrou que 3 em cada 5 pessoas preferem ônibus. Numa cidade de 20.000 moradores, isso equivale a cerca de:","opcoes":["12.000 pessoas","6.000 pessoas","15.000 pessoas","3.000 pessoas"],"explicacao":"20.000 × 3/5."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('ling','mat','fis','qui','bio','his','geo','fil') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
